FString FDungeonItem::EffectText() const
{
 const TCHAR* Texts[]={TEXT(""),TEXT("Bleed: 20% hit damage/sec for 4s"),TEXT("Poison: 14% hit damage/sec for 6s"),
 TEXT("Chill: slow movement 35% for 3s"),TEXT("Leech: heal 5% of direct damage"),TEXT("Harvest: heal 6 health per kill"),
 TEXT("Second wind: critical hits restore 12 stamina"),TEXT("Echo: every third strike splashes 35% damage"),
 TEXT("Execute: +35% damage below 30% enemy health"),TEXT("Berserk: +30% damage below 40% health"),
 TEXT("Aegis: reduce incoming damage by 12%")};
 return Texts[FMath::Clamp(Effect,0,10)];
}
float FDungeonItem::EquippedScale() const
{
 // Inventory icons are normalized for readability, not physical weapon size.
 // Scale around the grip in the renderer so resizing never moves the hand anchor.
 const float Scales[]={.90f,.82f,.90f,.68f,.82f,.85f,.80f,.78f,
     .67f,.90f,.86f,.80f,.86f,.80f,.94f,.83f,
     .90f,.72f,.84f,.82f,.80f,.86f,.66f,.94f};
 return CatalogId>=0&&CatalogId<24?Scales[CatalogId]:Icon==1?.85f:.92f;
}
FDungeonItem ADungeonGameMode::RollItem(int32 Definition,int32 Rarity,int32 Level)
{
 FDungeonItem I; I.CatalogId=FMath::Clamp(Definition,0,47); I.ItemLevel=FMath::Clamp(Level,1,100);
 I.Rarity=FMath::Clamp(Rarity,0,4); const auto& B=Catalog[I.CatalogId]; I.Name=B.Name;
 I.Slot=I.CatalogId<24?0:I.CatalogId<36?1:2;
 I.Icon=I.Slot*3+(I.CatalogId%3);
 const float Scale=(1.f+.08f*(I.ItemLevel-1))*(1.f+.3f*I.Rarity)*FMath::FRandRange(.88f,1.12f);
 if(I.Slot==0) { I.Attack=B.Power*Scale; I.Speed=B.Speed; }
 if(I.Slot==1) { I.Defense=B.Power*Scale; I.Vitality=8*Scale; I.Speed=B.Speed; }
 if(I.Slot==2) I.Vitality=B.Power*Scale;
 // Shuffle without replacement: no duplicate affix on one item.
 TArray<int32> Pool={0,1,2,3,4,5};
 for(int N=0;N<FMath::Min(I.Rarity,3);++N)
 {
  int Pick=FMath::RandRange(0,Pool.Num()-1),Affix=Pool[Pick]; Pool.RemoveAt(Pick);
  const float Q=FMath::FRandRange(.75f,1.f)*(1+.15f*I.Rarity);
  switch(Affix) {
   case 0:I.CritChance+=.035f*Q;break; case 1:I.CritDamage+=.22f*Q;break;
   case 2:I.Speed+=.09f*Q;break; case 3:I.Regen+=.18f*Q;break;
   case 4:I.Vitality+=12*Q;break; case 5:I.Defense+=4*Q;break;
  }
 }
 // Rare/epic signature effects let players try ailment builds before legendary drops.
 if(I.Rarity==4||(I.Rarity>=2&&FMath::FRand()<.4f)) I.Effect=B.Effect;
 return I;
}
bool ADungeonHero::HasEffect(int32 Effect) const
{ for(const auto& I:Equipment) if(!I.IsEmpty()&&I.Effect==Effect) return true; return false; }
void ADungeonHero::RebuildStats()
{
 AttackPower=24;Armor=8;MaxHealth=150;CritChance=.05f;CritMultiplier=1.5f;AttackSpeed=StaminaRegen=1;
 for(const auto& I:Equipment) if(!I.IsEmpty()) { AttackPower+=I.Attack;Armor+=I.Defense;MaxHealth+=I.Vitality;CritChance+=I.CritChance;CritMultiplier+=I.CritDamage;AttackSpeed+=I.Speed;StaminaRegen+=I.Regen; }
 CritChance=FMath::Clamp(CritChance,0.f,.75f);AttackSpeed=FMath::Clamp(AttackSpeed,.5f,2.f);
 Health=FMath::Clamp(Health,0.f,MaxHealth);
}
void ADungeonEnemy::UpdateAilments(float Dt)
{
 const float Damage=FMath::Min(Dt,BleedTime)*BleedDPS+FMath::Min(Dt,PoisonTime)*PoisonDPS;
 BleedTime=FMath::Max(0.f,BleedTime-Dt);PoisonTime=FMath::Max(0.f,PoisonTime-Dt);SlowTime=FMath::Max(0.f,SlowTime-Dt);
 // One non-proccing damage application. Death callback fires only through normal damage path.
 AilmentDamage+=Damage; AilmentTick+=Dt;
 if(AilmentDamage>0&&(AilmentTick>=.5f||(BleedTime<=0&&PoisonTime<=0)))
 { const float Pending=AilmentDamage; AilmentDamage=AilmentTick=0; TakeDungeonDamage(Pending); }
}
